// Des: Commands sync and purge, cloud client setup, alert helper
// Flo: pick the first configured object store + SQL vendor with a key file > sync local queue > purge at 90% > alert at 80% or when an upgrade is needed
// I/O: Ctx (config, keys) > stdout line or JSON, exit code; dry-run never touches the network
// ===================================================================
const std = @import("std"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const stor = @import("sy-clou-stor.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const sync = @import("sy-clou-sync.zig"); const purg = @import("ru-purg-clou.zig"); const outb = @import("sy-clou-outb.zig"); const aler = @import("ob-aler-send.zig"); const live = @import("nt-vend-live.zig"); const pipe = @import("ru-page-fetc.zig"); const cfgz = @import("cf-conf-load.zig"); const b2zz = @import("sy-clou-b2zz.zig"); const r2zz = @import("sy-clou-r2zz.zig"); const tigr = @import("sy-clou-tigr.zig");
const CF = .{ .keyz = 4096, .gibi = 1 << 30, .warn = 80 };
const Info = struct { mode: []const u8, pend_files: i64, pend_recs: i64, store: []const u8, sqlv: []const u8, note: []const u8 };
fn keyzText(ctx2: *const ctx3.Ctxz, keyd: []const u8, name: []const u8) ?[]const u8 { const path = std.fs.path.join(ctx2.allo, &.{ keyd, name }) catch return null; const raws = std.Io.Dir.cwd().readFileAlloc(ctx2.iozz, path, ctx2.allo, .limited(CF.keyz)) catch return null; const tex2 = std.mem.trim(u8, raws, " \t\r\n"); return if (tex2.len == 0) null else tex2; }
fn endpOfzz(conf: cfgz.Conf, name: []const u8) cfgz.Endp { if (std.mem.eql(u8, name, "b2zz")) return conf.clou_endp.b2zz; if (std.mem.eql(u8, name, "r2zz")) return conf.clou_endp.r2zz; if (std.mem.eql(u8, name, "tigr")) return conf.clou_endp.tigr; if (std.mem.eql(u8, name, "turs")) return conf.clou_endp.turs; if (std.mem.eql(u8, name, "neon")) return conf.clou_endp.neon; return conf.clou_endp.tidb; }
fn capzOfzz(conf: cfgz.Conf, name: []const u8) u64 { const gibz: u64 = if (std.mem.eql(u8, name, "b2zz")) conf.clou_capz_gbyt.b2zz else if (std.mem.eql(u8, name, "r2zz")) conf.clou_capz_gbyt.r2zz else conf.clou_capz_gbyt.tigr; return gibz * CF.gibi; }
const Pick = struct { s3zz: stor.S3zz, netz: sqlz.Netz, snam: []const u8, qnam: []const u8 };
fn pickMake(ctx2: *const ctx3.Ctxz, send: @import("nt-vend-base.zig").Send, keyd: []const u8, sidx: usize, qidx: usize) ?Pick { var sfou: usize = 0; var spic: ?stor.S3zz = null; var snam: []const u8 = ""; for (ctx2.conf.clou_stor_orde) |name| { const end2 = endpOfzz(ctx2.conf, name); if (end2.bukt.len == 0) continue; const ktzz = keyzText(ctx2, keyd, std.fmt.allocPrint(ctx2.allo, "{s}.key", .{name}) catch continue) orelse continue; const pair = stor.keyzPair(ktzz) catch continue; const cred = (if (std.mem.eql(u8, name, "b2zz")) b2zz.credMake(ctx2.allo, end2, pair) else if (std.mem.eql(u8, name, "r2zz")) r2zz.credMake(ctx2.allo, end2, pair) else tigr.credMake(ctx2.allo, end2, pair)) catch continue; if (sfou == sidx) { spic = .{ .cred = cred, .bukt = end2.bukt, .send = send, .gpaz = ctx2.init.gpa }; snam = name; break; } sfou += 1; }
var qfou: usize = 0; var qpic: ?sqlz.Netz = null; var qnam: []const u8 = ""; for (ctx2.conf.clou_sqlz_orde) |name| { const end2 = endpOfzz(ctx2.conf, name); if (end2.hos4.len == 0) continue; const ktzz = keyzText(ctx2, keyd, std.fmt.allocPrint(ctx2.allo, "{s}.key", .{name}) catch continue) orelse continue; const kind: sqlz.Kind = if (std.mem.eql(u8, name, "turs")) .turs else if (std.mem.eql(u8, name, "neon")) .neon else .tidb; if (qfou == qidx) { qpic = .{ .kind = kind, .end2 = end2, .key2 = ktzz, .send = send, .gpaz = ctx2.init.gpa }; qnam = name; break; } qfou += 1; } if (spic == null or qpic == null) return null; return .{ .s3zz = spic.?, .netz = qpic.?, .snam = snam, .qnam = qnam }; }
pub fn alerTryz(ctx2: *const ctx3.Ctxz, subj: []const u8, text: []const u8) void { const keyd = @import("ut-path-expa.zig").pathExpa(ctx2.allo, ctx2.home, ctx2.conf.vend_keyz_dirz) catch return; var lvzz: live.Live = .{ .time_mill = 15000 }; const alzz = aler.alerLoad(ctx2.allo, ctx2.iozz, keyd, ctx2.conf, lvzz.send(), ctx2.init.gpa); _ = aler.alerSend(&alzz, ctx2.allo, ctx2.iozz, subj, text) catch {}; }
pub fn runzSync(ctx2: *const ctx3.Ctxz) !u8 { if (!ctx3.dbzzHave(ctx2)) { try ctx3.outz(ctx2, "nothing to sync yet"); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const keyd = @import("ut-path-expa.zig").pathExpa(ctx2.allo, ctx2.home, ctx2.conf.vend_keyz_dirz) catch return error.BadConfig; var lvzz: live.Live = .{ .time_mill = ctx2.conf.fetc_time_seco * 1000 }; const sndz = lvzz.send(); const first = pickMake(ctx2, sndz, keyd, 0, 0);
if (!ctx2.args.live) { const info: Info = .{ .mode = "dry-run", .pend_files = try outb.outbCont(&dbzz, 0), .pend_recs = 0, .store = if (first) |pkzz| pkzz.snam else "none", .sqlv = if (first) |pkzz| pkzz.qnam else "none", .note = "pending counts include files and records; add --live to upload" }; try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, info, try std.fmt.allocPrint(ctx2.allo, "dry-run | {d} queued | store {s} | sql {s} | add --live to upload", .{ info.pend_files, info.store, info.sqlv }))); return 0; }
if (first == null) return error.NotConfigured; var tri2: usize = 0; var las2: anyerror = error.Fail; while (tri2 < 3) : (tri2 += 1) { var pkzz = pickMake(ctx2, sndz, keyd, tri2, tri2) orelse break; var synz: sync.Sync = .{ .iozz = ctx2.iozz, .dbzz = &dbzz, .dirz = ctx2.dirz, .conf = ctx2.conf, .store = pkzz.s3zz.store(), .sql2 = pkzz.netz.sql2() }; const nowz = pipe.nowzMill(ctx2.iozz); const rslt = sync.syncRunz(&synz, ctx2.allo, nowz) catch |err3| { las2 = err3; continue; }; const prsz = purg.purgRunz(&synz, ctx2.allo, nowz, capzOfzz(ctx2.conf, pkzz.snam)) catch |err3| blkz: { las2 = err3; break :blkz purg.Pres{}; }; if (prsz.act2 == .upgr) alerTryz(ctx2, "scra cloud full", "cloud is at 90% and clou_poli_mode is upgr: upgrade the plan or switch to purg"); if (prsz.cap2 > 0 and prsz.usa2 * 100 >= prsz.cap2 * CF.warn and prsz.act2 == .none) alerTryz(ctx2, "scra cloud 80%", "cloud storage passed 80% of the free cap"); const plai = try std.fmt.allocPrint(ctx2.allo, "sync | {d} records | {d} files in {s} | purged {d} packs | store {s} sql {s}", .{ rslt.recs, rslt.fil2, rslt.pack, prsz.pac4, pkzz.snam, pkzz.qnam }); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, .{ .recs = rslt.recs, .fil2 = rslt.fil2, .pack = rslt.pack, .purged = prsz.pac4, .store = pkzz.snam, .sqlv = pkzz.qnam }, plai)); return 0; } return las2; }
